querydefinitiedocument.graphql_document:
query NieuweAanmeldingen($limit: Int = 100, $offset: Int = 0) {
  full_initiatieven_list(
    filter: { aanmeldstatussen: { status: { in: ["nieuwe_aanmelding", "in_behandeling"] } } },
    limit: $limit, offset: $offset
  ) {
    id
    weergavenaam
    aanmeldstatussen { status toelichting }
    producten { naam type CG_laag website }
    planningen { fase startdatum }
    initiatief_organisaties { rol weergavenaam }
    betrokken_organisatie { type }
  }
}
